  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 3.4,
        "text": "OpenAIGoogle 微软 都在用同一个协议"
      },
      {
        "start": 3.4,
        "end": 6.6,
        "text": "它叫mcp 两分钟 将明白它"
      },
      {
        "start": 7.6,
        "end": 10,
        "text": "上期 我们给AI装了技能帮"
      },
      {
        "start": 10,
        "end": 11.8,
        "text": "它知道该怎么做了"
      },
      {
        "start": 11.8,
        "end": 14.4,
        "text": "和它的手 够不找你的东西"
      },
      {
        "start": 14.4,
        "end": 17.8,
        "text": "异力 油箱 数据库 带马仓库"
      },
      {
        "start": 17.8,
        "end": 19.6,
        "text": "想让它用上这些"
      },
      {
        "start": 19.6,
        "end": 22.2,
        "text": "每个工具都得单写一套对接"
      },
      {
        "start": 22.2,
        "end": 24.4,
        "text": "接口形状还各不相同"
      },
      {
        "start": 25.4,
        "end": 28.8,
        "text": "再换一个AI应用 又得从头写一遍"
      },
      {
        "start": 28.8,
        "end": 30.8,
        "text": "三个应用皆四的攻击"
      },
      {
        "start": 30.8,
        "end": 32.8,
        "text": "就是下套带马"
      },
      {
        "start": 32.8,
        "end": 34.8,
        "text": "工具越多 线越乱"
      },
      {
        "start": 34.8,
        "end": 36.8,
        "text": "2024年11月"
      },
      {
        "start": 36.8,
        "end": 38.8,
        "text": "and traffic 它原来一个形务"
      },
      {
        "start": 38.8,
        "end": 40.8,
        "text": "MSTP模型上下文学一"
      },
      {
        "start": 40.8,
        "end": 43.8,
        "text": "你可以把它想成AI的USBC"
      },
      {
        "start": 43.8,
        "end": 45.8,
        "text": "接口统一 谁都能插"
      },
      {
        "start": 45.8,
        "end": 47.8,
        "text": "原来要十二套对接"
      },
      {
        "start": 47.8,
        "end": 49.8,
        "text": "现在只要三架四等于机场"
      },
      {
        "start": 50.8,
        "end": 52.8,
        "text": "mcp 理由三个角色"
      },
      {
        "start": 52.8,
        "end": 54.8,
        "text": "主机 理用的AI 应用"
      },
      {
        "start": 54.8,
        "end": 57.8,
        "text": "客户端 再成经理负责连线"
      },
      {
        "start": 57.8,
        "end": 60.8,
        "text": "服务器 把工具帮成统一接口"
      },
      {
        "start": 60.8,
        "end": 63.8,
        "text": "服务器能提供三样东西"
      },
      {
        "start": 63.8,
        "end": 67.8,
        "text": "工具 将AI去做事 资源 让AI独资料 提示词"
      },
      {
        "start": 67.8,
        "end": 69.8,
        "text": "常用任务的模板"
      },
      {
        "start": 69.8,
        "end": 73.8,
        "text": "理由你说 帮我冤明天下午的会"
      },
      {
        "start": 73.8,
        "end": 75.8,
        "text": "AI先问服务器 你会什么"
      },
      {
        "start": 75.8,
        "end": 78.8,
        "text": "拿到查日记 调用 结果回来"
      },
      {
        "start": 78.8,
        "end": 82.8,
        "text": "下午三点有空 再调用发邀请 搞定"
      },
      {
        "start": 82.8,
        "end": 85.8,
        "text": "它们这间设的是机场RPC"
      },
      {
        "start": 85.8,
        "end": 87.8,
        "text": "一年之内 OPEN AI"
      },
      {
        "start": 87.8,
        "end": 89.8,
        "text": "估计相机进入二零二五年十二月"
      },
      {
        "start": 89.8,
        "end": 91.8,
        "text": "它被交给了那次基金会过管"
      },
      {
        "start": 91.8,
        "end": 95.8,
        "text": "STP每月下载量超过 九千七百万次"
      },
      {
        "start": 96.8,
        "end": 99.8,
        "text": "估计 接口通了 风险也更接近来了"
      },
      {
        "start": 99.8,
        "end": 103.8,
        "text": "特意着工具描述 可能又到AI线路数据"
      },
      {
        "start": 103.8,
        "end": 106.8,
        "text": "所以 只装新的过得服务器"
      },
      {
        "start": 106.8,
        "end": 108.8,
        "text": "C 口叫AI怎么做"
      },
      {
        "start": 108.8,
        "end": 110.8,
        "text": "mcp 让AI够得着"
      },
      {
        "start": 110.8,
        "end": 112.8,
        "text": "一个是说明书 一个是接口"
      },
      {
        "start": 112.8,
        "end": 114.8,
        "text": "去接口,假期见!"
      }
